type StepDefinition = StepDefinition {
  id: String,
  needs: List(String),
  amount: Int,
  failures: Int
}

type Workflow = Workflow {
  steps: List(StepDefinition),
  commands: List(Command),
  max_attempts: Int,
  retry_delay: Int
}

type StepState = StepState {
  id: String,
  status: StepStatus,
  attempts: Int,
  ready_at: Int
}

type RunState = RunState {
  id: String,
  status: RunStatus,
  cancel_requested: Bool,
  steps: List(StepState)
}

type ServiceCall = ServiceCall {
  key: ActionKey,
  attempt: Int,
  kind: CallKind,
  outcome: CallOutcome
}

type MockService = MockService {
  calls: List(ServiceCall),
  effects: List(Effect),
  effect_cache: List((ActionKey, Bool))
}

fn step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at))])

fn run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(step_json, run.steps)))])

fn call_json(call : ServiceCall) : Json =
  JObj([("kind", JStr(kind_str(call.kind))), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(outcome_str(call.outcome)))])

fn result_json(sim : Simulator) : Json =
  let final_fields = append(snapshot_fields(snapshot(sim)),
    [("calls", JArr(map(call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("observations", JArr(map(snapshot_json, sim.observations))), ("final", JObj(final_fields))])

fn select_step(now : Int, inflight : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let is_running = step_is_running(step)
      let is_pending = step_is_pending(step)
      let is_active = run_is_active(run)
      let ready_now = step.ready_at <= now
      let deps_ok = deps_satisfied(run, definition.needs)

      let ready =
        if inflight then is_running
        else is_active && is_pending && ready_now && deps_ok

      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, inflight, run, more_states, more_definitions)
    _ => None

fn cancel_pending_step(step : StepState) : StepState =
  if step_is_pending(step) then
    StepState { ..step, status = StepCancelled }
  else step

fn block_pending_step(step : StepState) : StepState =
  if step_is_pending(step) then
    StepState { ..step, status = Blocked }
  else step

fn make_running(step : StepState) : StepState =
  if step_is_pending(step) then
    StepState { ..step, status = Running, attempts = step.attempts + 1 }
  else step

fn tick(sim : Simulator, workflow : Workflow) : Result(Simulator, String) =
  if not(sim.up) then Err("PROCESS_DOWN")
  else
    match select_action(sim, workflow) of
      None => Ok(sim)
      Some(action) =>
        let running = make_running(action.step)
        let begun_run = replace_step(action.run, running)
        let begun = replace_run(sim, begun_run)
        let key = ActionKey { run_id = action.run.id, step_id = running.id }

        match execute(begun.service, key, action.definition.amount, running.attempts, action.definition.failures) of
          Ok((service_after_exec, outcome)) =>
            match outcome of
              Applied =>
                let completed = replace_step(begun_run, StepState { ..running, status = StepSucceeded })
                let finished =
                  if all_steps_succeeded(completed.steps) then
                    RunState { ..completed, status = RunSucceeded }
                  else completed
                Ok(replace_run(Simulator { ..begun, service = service_after_exec }, finished))
              Replayed =>
                let completed = replace_step(begun_run, StepState { ..running, status = StepSucceeded })
                let finished =
                  if all_steps_succeeded(completed.steps) then
                    RunState { ..completed, status = RunSucceeded }
                  else completed
                Ok(replace_run(Simulator { ..begun, service = service_after_exec }, finished))
              Transient =>
                if running.attempts >= workflow.max_attempts then
                  let failed_step = StepState { ..running, status = Failed }
                  let failed_run = replace_step(begun_run, failed_step)
                  let blocked_run = RunState { ..failed_run, status = RunFailed, steps = mark_pending_blocked(failed_run.steps) }
                  Ok(replace_run(Simulator { ..begun, service = service_after_exec }, blocked_run))
                else
                  let retry_at = sim.now + workflow.retry_delay
                  if retry_at > time_limit() then
                    Err("TIME_OVERFLOW")
                  else
                    let retried = StepState { ..running, status = Pending, ready_at = retry_at }
                    let updated_run = replace_step(begun_run, retried)
                    Ok(replace_run(Simulator { ..begun, service = service_after_exec }, updated_run))
              _ => Ok(sim)
          Err(_) => Ok(sim)

fn apply_cancel(sim : Simulator, run_id : String) : Result(Simulator, String) =
  if not(sim.up) then Err("PROCESS_DOWN")
  else
    match find_run(sim.runs, run_id) of
      None => Err("UNKNOWN_RUN")
      Some(run) =>
        if is_run_terminal(run.status) then
          Ok(sim)
        else
          let cancelled_steps = mark_pending_cancelled(run.steps)
          let has_running = any(\(step) -> step_is_running(step), cancelled_steps)
          let new_status = if has_running then Cancelling else RunCancelled
          let updated_run = RunState { ..run, cancel_requested = true, status = new_status, steps = cancelled_steps }
          Ok(replace_run(sim, updated_run))

fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Start(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else if any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
      else
        let run = RunState { id = id, status = Active, cancel_requested = false,
          steps = map(\(definition) -> new_step(sim.now, definition), workflow.steps) }
        Ok(Simulator { ..sim, runs = append(sim.runs, [run]) })
    Tick(checkpoint) =>
      match checkpoint of
        None => 
          if any(\(run) -> run_is_cancelling(run), sim.runs) then
            tick_cancelling(sim, workflow)
          else
            tick(sim, workflow)
        Some(cp) => tick_with_checkpoint(sim, workflow, Some(cp))
    Advance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok(Simulator { ..sim, now = sim.now + by })
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    Crash => Ok(Simulator { ..sim, up = false })
    Restart => 
      if sim.up then Err("PROCESS_UP")
      else Ok(Simulator { ..sim, up = true })
    Cancel(id) => apply_cancel(sim, id)

fn count_transient_failures(calls : List(ServiceCall), key : ActionKey) : Int =
  length(filter(\(call) -> call.key.run_id == key.run_id && call.key.step_id == key.step_id 
                && call.kind == Execute && call.outcome == Transient, calls))

fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : Result((MockService, CallOutcome), String) =
  match find(\(pair) -> fst(pair).run_id == key.run_id && fst(pair).step_id == key.step_id, service.effect_cache) of
    Some(_) =>
      let call = ServiceCall { key = key, attempt = attempt, kind = Execute, outcome = Replayed }
      Ok((MockService { ..service, calls = append(service.calls, [call]) }, Replayed))
    None =>
      let transient_count = count_transient_failures(service.calls, key)
      if transient_count < failures then
        let call = ServiceCall { key = key, attempt = attempt, kind = Execute, outcome = Transient }
        Ok((MockService { ..service, calls = append(service.calls, [call]) }, Transient))
      else
        let call = ServiceCall { key = key, attempt = attempt, kind = Execute, outcome = Applied }
        let updated = MockService {
          ..service,
          calls = append(service.calls, [call]),
          effects = append(service.effects, [Effect { key = key, amount = amount }]),
          effect_cache = append(service.effect_cache, [(key, true)])
        }
        Ok((updated, Applied))

fn fields(value : Json, required : List(String), optional : List(String)) : Result(List((String, Json)), String) =
  match value of
    JObj(pairs) =>
      let keys = map(\(pair) -> fst(pair), pairs)
      let _ = ensure(unique(keys) && all(\(key) -> elem(key, keys), required)
          && all(\(key) -> elem(key, append(required, optional)), keys), "INVALID_INPUT")?
      Ok(pairs)
    _ => Err("INVALID_INPUT")

fn valid_id_bytes(s : String, i : Int) : Bool =
  if i >= byte_len(s) then true
  else
    let c = byte_at(s, i)
    ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)
      || (c >= 48 && c <= 57) || c == 95 || c == 45) && valid_id_bytes(s, i + 1)

fn parse_checkpoint(obj : List((String, Json))) : Result(Option(Checkpoint), String) =
  match find(\(pair) -> fst(pair) == "crash_at", obj) of
    None => Ok(None)
    Some(pair) =>
      match snd(pair) of
        JStr(name) =>
          if name == "after_begin" then Ok(Some(AfterBegin))
          elif name == "after_call" then Ok(Some(AfterCall))
          else Err("INVALID_INPUT")
        _ => Err("INVALID_INPUT")

fn acyclic(remaining : List(StepDefinition), visited : List(String)) : Bool =
  if is_nil(remaining) then true
  else
    let ready = filter(\(step) -> all(\(dep) -> elem(dep, visited), step.needs), remaining)
    if is_nil(ready) then false
    else
      let seen = append(visited, map(\(step) -> step.id, ready))
      acyclic(filter(\(step) -> not(elem(step.id, seen)), remaining), seen)

fn validate_graph(steps : List(StepDefinition)) : Result(Unit, String) =
  let ids = map(\(step) -> step.id, steps)
  let _ = ensure(unique(ids), "DUPLICATE_STEP")?
  let _ = ensure(all(\(step) -> all(\(dep) -> elem(dep, ids), step.needs), steps), "UNKNOWN_DEPENDENCY")?
  ensure(acyclic(steps, []), "DEPENDENCY_CYCLE")
